export type Article={slug:string;title:string;description:string;date:string;updated?:string;minutes:number;category:string;links?:[string,string][];blocks:Block[]};
const allArticles:Article[]=[
{slug:'wat-kost-maatwerk-software',title:'Wat kost maatwerk software? Zo beoordeel je een offerte',description:'Welke keuzes bepalen de kosten van maatwerk software? Vergelijk rollen, koppelingen, migratie en beheer met deze praktische offertechecklist.',date:'2026-10-29',minutes:6,category:'Maatwerk',links:[['Softwarebedrijf in Apeldoorn','/softwarebedrijf-apeldoorn'],['Maatwerk software laten ontwikkelen','/maatwerk-software-laten-ontwikkelen'],['Bekijk het OME Partnerportaal (demo)','/projecten/ome-partnerportaal'],['Bekijk AIGWise met demodata','/projecten/aigwise']],blocks:[
 {p:['Een prijs voor maatwerk software is pas bruikbaar als duidelijk is wat je ervoor krijgt. Een eenvoudig intern overzicht vraagt iets anders dan een portaal voor klanten, medewerkers en partners. Daarom begint een goede offerte met je werkproces: wie doet wat, welke informatie is nodig en wanneer is de eerste versie bruikbaar?','Deze gids helpt je de omvang af te bakenen en offertes op inhoud te vergelijken. We noemen geen gemiddeld bedrag: zonder concrete eisen zegt dat weinig over jouw project.']},
 {h:'Welke onderdelen bepalen de bouwkosten?',ul:['Gebruikersrollen: een beheerder, medewerker en klant kunnen elk andere schermen en toegangsrechten nodig hebben.','Werkprocessen: aanvragen, goedkeuren, documenten aanleveren en uitzonderingen afhandelen moeten worden uitgewerkt en getest.','Koppelingen: de mogelijkheden, documentatie en beperkingen van je bestaande systemen bepalen hoeveel maatwerk nodig is.','Gegevens overzetten: oude gegevens opschonen, velden koppelen en een migratie controleren is een apart onderdeel.','Ontwerp en toegankelijkheid: ook een interne toepassing moet begrijpelijk werken op de apparaten van je gebruikers.','Testen en opleveren: denk aan gebruikersacceptatie, foutmeldingen, rechten, instructies en de overstap naar het nieuwe proces.']},
 {h:'Begin met één volledig werkproces',p:['Een eerste versie hoeft niet alles te kunnen. Kies een proces dat van begin tot eind bruikbaar is. Bijvoorbeeld: een partner dient een aanvraag in, een medewerker beoordeelt die en de partner ziet de actuele status. Rapportages en extra automatiseringen kunnen daarna volgen.','Leg ook vast wat buiten de eerste fase valt. Een ontbrekende rapportage is iets anders dan ontbrekende toegangscontrole. Noodzakelijke beveiliging, foutafhandeling en back-ups horen bij een bruikbare basis.'],ol:['Beschrijf de aanleiding en het gewenste eindpunt van het proces.','Noteer wie elke stap uitvoert en welke gegevens nodig zijn.','Kies de functies die noodzakelijk zijn voor een eerste bruikbare versie.','Spreek concrete acceptatiecriteria af: wat moet je samen kunnen demonstreren?']},
 {h:'Een portaal en een administratief platform vragen andere keuzes',p:['Het OME Partnerportaal laat een opzet zien met zoekopdrachten, rollen en statusopvolging. Voor zo’n proces zijn de aanvraag, de rechten en het overzicht voor de opdrachtgever belangrijke gespreksonderwerpen. De openbare schermafbeelding is een demo met voorbeelddata.','AIGWise brengt dossier-, factuur- en betaaloverzichten samen. Bij een dergelijke toepassing moet je bepalen hoe informatie aan het juiste dossier wordt gekoppeld en hoe gebruikers de historie terugvinden. Ook hier tonen de openbare schermafbeeldingen demodata.','Deze voorbeelden maken functies bespreekbaar. Ze zijn geen prijscategorieën: de precieze eisen, koppelingen en beheerafspraken bepalen de omvang van jouw project.']},
 {h:'Reken ook met de kosten na oplevering',p:['Vraag naast de bouwprijs om inzicht in hosting, opslag, externe diensten, onderhoud en ondersteuning. Een koppeling kan bijvoorbeeld afhankelijk zijn van een betaald abonnement bij een andere leverancier. Vraag wie dat contract afsluit en welke limieten gelden.','Leg vast wie updates uitvoert, hoe back-ups worden gecontroleerd en waar je terechtkunt bij een storing. Maak ook onderscheid tussen het herstellen van een fout en het toevoegen van een nieuwe functie. Doorontwikkeling vraagt een eigen afspraak.']},
 {h:'Vaste prijs per fase of werken op uren?',p:['Een vaste prijs per afgebakende fase geeft duidelijkheid als de eisen voldoende bekend zijn. Spreek dan af hoe je omgaat met nieuwe wensen. Werken op uren kan passen bij onderzoek of een veranderend proces, maar vraagt zicht op bestede tijd, prioriteiten en een budgetgrens.','Vergelijk daarom niet alleen het eindbedrag. Een goedkope offerte zonder migratie, testen of beheer kan minder omvatten dan een hoger voorstel. Laat verschillen uitschrijven voordat je beslist.']},
 {h:'Checklist voor het vergelijken van softwareoffertes',ol:['Welke gebruikers, schermen en werkprocessen zijn inbegrepen?','Welke koppelingen en migraties zijn uitgewerkt, en welke aannames staan nog open?','Wanneer is een fase klaar en hoe wordt die geaccepteerd?','Wat zijn de eenmalige en terugkerende kosten, inclusief externe leveranciers?','Wat spreken we af over broncode, eigendom, toegang tot accounts en export van gegevens?','Wie verzorgt onderhoud, ondersteuning en een eventuele overstap naar een andere partij?','Hoe worden nieuwe wensen begroot en goedgekeurd?']},
 {h:'Je softwarevraag concreet maken',p:['Neem naar een kennismaking één procesbeschrijving mee, plus voorbeelden van de formulieren of overzichten die je nu gebruikt. Verwijder persoonsgegevens uit voorbeelden die niet nodig zijn. Noteer ook hoeveel mensen ermee werken en welke systemen moeten blijven.','NiMaGo werkt vanuit Apeldoorn aan maatwerk software voor ondernemers en organisaties. We beginnen bij het proces en maken een voorstel met scope en prijs per fase. Via de links hieronder kun je voorbeelden bekijken of een vrijblijvende kennismaking plannen.']}
]},

{slug:'wat-kost-een-website',title:`Wat kost een website laten maken? Dit bepaalt de prijs`,description:`Geen prijslijst, wel een eerlijk overzicht van wat de kosten van een website bepaalt en hoe je offertes goed vergelijkt.`,date:'2026-10-27',minutes:5,category:'Websites',blocks:[
 {p:[`“Wat kost een website?” is de eerste vraag die bijna elke ondernemer stelt. Het eerlijke antwoord is: dat hangt ervan af. Dat is geen ontwijkend antwoord. Een site van vijf pagina’s met een duidelijke boodschap is iets anders dan een webshop met koppelingen naar je voorraad. Hieronder lees je wat de prijs bepaalt, zodat je offertes goed kunt vergelijken.`]},
 {h:`De vijf dingen die de prijs bepalen`,ul:[`Omvang: hoeveel pagina’s en wat voor soorten pagina’s heb je nodig?`,`Ontwerp: een bestaand sjabloon aanpassen is iets anders dan een ontwerp op maat dat bij je merk past.`,`Functionaliteit: een contactformulier is simpel. Afspraken boeken, betalen, inloggen of koppelingen met andere systemen kosten meer tijd.`,`Inhoud: wie schrijft de teksten en wie zorgt voor foto’s? Goede inhoud is vaak de langste stap.`,`Beheer na oplevering: hosting, updates en support horen bij een website die blijft werken.`]},
 {h:`Sjabloon of maatwerk?`,p:[`Een sjabloon is sneller en voordeliger en werkt goed als je een eenvoudige site nodig hebt. Maatwerk loont als je je wilt onderscheiden, als je specifieke wensen hebt of als de site een belangrijke rol speelt in je verkoop. Een goede bouwer vertelt eerlijk welke van de twee bij jou past, ook als dat de goedkopere is.`]},
 {h:`De kosten na oplevering`,p:[`Een website is geen eenmalig project. Reken ook op een domeinnaam, hosting en onderhoud: updates, beveiliging en kleine aanpassingen. Vraag in de offerte altijd wat daarvan is inbegrepen en wat apart wordt gefactureerd.`]},
 {h:`Zo vergelijk je offertes`,ol:[`Wat is inbegrepen? Kijk naar het aantal pagina’s, de functies en het aantal feedbackrondes.`,`Wie is eigenaar van het eindresultaat, zoals ontwerp en code?`,`Zijn hosting en onderhoud inbegrepen, en voor hoe lang?`,`Wat is de planning, en wat heeft de bouwer van jou nodig om die te halen?`,`Wat valt er niet onder? Een goede offerte noemt dat zelf.`]},
 {h:`Onze aanpak`,p:[`Bij NiMaGo beginnen we met een gesprek. Daarna krijg je een voorstel met een duidelijke scope en prijs, bij voorkeur per afgebakende fase. Zo weet je vooraf waar je aan toe bent en kun je tussentijds bijsturen. Wil je weten wat jouw project kan kosten? Plan een vrijblijvende kennismaking.`]}]},
{slug:'shopify-of-maatwerk-webshop',title:`Shopify of een maatwerk webshop? Zo maak je de keuze`,description:`Een platform zoals Shopify is vaak de snelste route naar een goede webshop. Maar wanneer is maatwerk slimmer? Een praktische vergelijking.`,date:'2026-10-27',minutes:5,category:'Webshops',blocks:[
 {p:[`Wie een webshop wil starten, komt snel bij dezelfde vraag uit: kiezen voor een platform zoals Shopify, of laten bouwen wat je precies nodig hebt? Beide kunnen de juiste keuze zijn. Dit helpt je bepalen welke past.`]},
 {h:`Wanneer past een platform als Shopify?`,ul:[`Je wilt snel live en je assortiment is standaard: producten, varianten, betalen en verzenden.`,`Je wilt niet zelf zorgen voor beveiliging, betalingen en onderhoud van de basis.`,`Je werkt het liefst met een systeem dat je team snel leert beheren.`,`Je maakt gebruik van het grote ecosysteem van apps voor marketing, boekhouding of verzending.`]},
 {h:`Wanneer is maatwerk slimmer?`,ul:[`Je proces wijkt af, bijvoorbeeld bij speciale prijsafspraken, configuratoren of tweedehands toestellen met unieke gegevens per stuk.`,`Je moet de winkel diep koppelen aan eigen systemen, zoals voorraad, productie of een CRM.`,`Je wilt volledige controle over gegevens en gedrag.`,`Een standaardplatform dwingt je steeds om een beperking heen te werken.`]},
 {h:`Een slimme tussenweg`,p:[`Vaak is de beste oplossing een combinatie: een platform voor de basis en maatwerk voor wat jou onderscheidt. Denk aan een eigen thema met extra productgegevens, of een koppeling die automatisch voorraad en bestellingen synchroniseert. Zo houd je de voordelen van een bewezen platform en bouw je alleen wat echt waarde toevoegt.`]},
 {h:`Vragen om jezelf te stellen`,ol:[`Wat verkoop ik, en wijkt dat af van wat een standaardwinkel aankan?`,`Met welke systemen moet de winkel samenwerken?`,`Wie beheert de winkel, en hoe technisch is die persoon?`,`Wat is mijn planning en budget, nu en over twee jaar?`]},
 {p:[`Twijfel je? Leg je situatie aan ons voor. We adviseren wat past, ook als dat een standaardplatform is.`]}]},
{slug:'wanneer-loont-automatiseren',updated:'2026-10-28',title:`Wanneer loont het om processen te automatiseren?`,description:`Niet alles hoef je te automatiseren. Deze signalen laten zien waar je tijd wint, en waar je beter even wacht.`,date:'2026-10-27',minutes:4,category:'Automatisering',blocks:[
 {p:[`Automatiseren klinkt aantrekkelijk, maar niet elk proces is het waard. Een goede automatisering bespaart tijd, voorkomt fouten en geeft je team ruimte voor werk waar mensen goed in zijn. Een slechte automatisering kost vooral geld en onderhoud. Zo herken je het verschil.`]},
 {h:`Vijf signalen dat automatiseren loont`,ul:[`Je tikt dezelfde gegevens op meerdere plekken in, bijvoorbeeld van een bestelling naar je boekhouding.`,`Een taak komt wekelijks of dagelijks terug en volgt altijd dezelfde stappen.`,`Fouten komen vooral door handmatig overtypen of kopiëren.`,`Je team wacht regelmatig op informatie die in een ander systeem staat.`,`Het proces groeit mee met je omzet en wordt een knelpunt.`]},
 {h:`Wanneer je beter even wacht`,ul:[`Het proces verandert nog steeds. Eerst stabiliseren, dan automatiseren.`,`Het gebeurt zelden. Een uur handwerk per kwartaal rechtvaardigt geen maatwerk.`,`Niemand weet precies hoe het proces nu werkt. Begin dan met het in kaart brengen.`]},
 {h:`Zo pak je het aan`,ol:[`Breng het proces in kaart: wat gebeurt er, wie doet wat, en waar gaat het mis?`,`Kies één knelpunt met duidelijke winst, niet alles tegelijk.`,`Begin klein en test met echte situaties.`,`Zorg voor bewaking: je wilt weten wanneer een koppeling stopt.`]},
 {h:`Reken met je eigen proces, niet met een beloofd percentage`,p:[`Noteer eerst hoe vaak een taak voorkomt, hoeveel minuten die werkelijk kost en hoeveel tijd na automatisering nodig blijft voor controle. Het verschil is je mogelijke tijdwinst. Reken daarnaast bouw, abonnementen, onderhoud en foutafhandeling mee. Zonder deze nulmeting is een besparingsclaim vooral een gok.`],ul:[`Tijdwinst per maand = aantal taken × (huidige minuten − resterende minuten) ÷ 60.`,`Vergelijk de waarde van die uren met de totale kosten van bouw en beheer.`,`Spreek af wie uitzonderingen controleert en wie een storing oplost.`]},
 {h:`Wat als een koppeling uitvalt?`,p:[`Een bruikbare automatisering houdt bij welke gegevens zijn verwerkt en voorkomt dat dezelfde bestelling of factuur twee keer wordt aangemaakt. Spreek af hoe je fouten ziet, wanneer opnieuw wordt geprobeerd en welke handmatige route overblijft. Test ook ontbrekende velden, gewijzigde rechten en een systeem dat tijdelijk niet bereikbaar is.`]},
 {h:`En AI?`,p:[`AI kan helpen bij het samenvatten, sorteren of herkennen van gegevens. Maar alleen als het een echt probleem oplost en je weet welke gegevens waarheen gaan. Wij gebruiken AI waar het aantoonbaar helpt, niet omdat het kan.`]}]},
{slug:'website-onderhoud',title:`Website-onderhoud: wat is het en waarom heb je het nodig?`,description:`Een website die niet wordt onderhouden, wordt langzamer, onveiliger en minder vindbaar. Dit hoort er normaal bij.`,date:'2026-10-27',minutes:4,category:'Onderhoud',blocks:[
 {p:[`Veel ondernemers zien hun website als een project dat af is op de dag van oplevering. In werkelijkheid verandert de techniek eromheen voortdurend. Onderhoud zorgt dat je site blijft werken, veilig is en meegroeit.`]},
 {h:`Wat hoort bij onderhoud?`,ul:[`Updates van software, plug-ins en bibliotheken, zodat bekende kwetsbaarheden worden gedicht.`,`Bewaking: je wilt weten dat de site bereikbaar is en snel blijft.`,`Back-ups, zodat je bij een storing snel kunt herstellen.`,`Kleine aanpassingen: een tekst, een foto, een nieuw formulier.`,`Advies over wat de site beter kan maken.`]},
 {h:`Wat gebeurt er zonder onderhoud?`,p:[`Een site zonder updates is een makkelijk doelwit voor misbruik. Daarnaast kan hij trager worden, kunnen functies breken door browserwijzigingen en daalt de vindbaarheid. Het herstellen van een verwaarloosde site kost meestal meer dan regelmatig onderhoud.`]},
 {h:`Hoe kies je een onderhoudsafspraak?`,ol:[`Kijk wat er precies is inbegrepen en hoeveel tijd je maandelijks hebt voor aanpassingen.`,`Vraag hoe snel er wordt gereageerd bij een storing.`,`Check hoe back-ups werken en waar ze staan.`,`Kies een vast maandbedrag of een bundel uren, afhankelijk van hoe vaak je wijzigingen verwacht.`]},
 {p:[`Bij NiMaGo kun je onderhoud en doorontwikkeling afspreken, ook voor websites die we niet zelf bouwden. We kijken eerst eerlijk naar de staat van de site.`]}]},
{slug:'klantportaal-laten-bouwen',title:`Wat is een klantportaal en wanneer heb je er een nodig?`,description:`Een klantportaal geeft klanten of partners zelf toegang tot hun gegevens. Dit zijn de voordelen en de valkuilen.`,date:'2026-10-27',minutes:4,category:'Maatwerk',blocks:[
 {p:[`Een klantportaal is een beveiligde omgeving waar klanten of partners zelf kunnen inloggen om hun gegevens te bekijken of acties uit te voeren. Denk aan het volgen van een aanvraag, het inzien van facturen of het uploaden van documenten.`]},
 {h:`Wanneer helpt een portaal?`,ul:[`Klanten bellen of mailen steeds met dezelfde vragen over status of documenten.`,`Je deelt gevoelige gegevens per e-mail, wat riskant en onoverzichtelijk is.`,`Partners moeten zelf aanvragen kunnen indienen en volgen.`,`Je wilt dat meerdere mensen in één overzicht dezelfde gegevens zien.`]},
 {h:`Waar moet je op letten?`,ul:[`Rollen en rechten: wie mag wat zien en doen?`,`Veilig inloggen: bijvoorbeeld met een link per e-mail of een tweede stap.`,`Eenvoud: een portaal moet minder werk opleveren, niet meer.`,`Beheer: wie voegt gebruikers toe en lost problemen op?`]},
 {h:`Zo begin je`,ol:[`Beschrijf welke vragen of taken je het meest tijd kosten.`,`Bepaal welke gegevens klanten zelf mogen zien.`,`Start met een kleine versie die het grootste knelpunt oplost.`,`Breid uit op basis van wat gebruikers echt gebruiken.`]},
 {p:[`Wij bouwden onder meer portalen voor partners die zoekopdrachten indienen en volgen. Wil je weten of een portaal bij jou past? We denken graag mee.`]}]},
{slug:'api-koppelingen-uitgelegd',title:`API-koppelingen uitgelegd: zo praten je systemen met elkaar`,description:`Een API is de manier waarop software gegevens uitwisselt. Wat betekent dat voor jouw webshop, boekhouding of CRM?`,date:'2026-10-27',minutes:4,category:'Koppelingen',blocks:[
 {p:[`Je gebruikt waarschijnlijk meerdere systemen: een webshop, een boekhoudpakket, een CRM, een mailprogramma. Een API-koppeling zorgt dat die systemen automatisch gegevens uitwisselen, zodat jij ze niet hoeft over te typen.`]},
 {h:`Wat is een API?`,p:[`API staat voor application programming interface. Je kunt het zien als een loket: een systeem laat via vaste regels toe dat andere software gegevens opvraagt of toevoegt. Zo kan je webshop een bestelling doorgeven aan je boekhouding.`]},
 {h:`Wat kun je ermee?`,ul:[`Bestellingen automatisch naar je administratie sturen.`,`Voorraad tussen webshop en magazijn synchroniseren.`,`Nieuwe aanvragen direct in je CRM zetten.`,`Berichten of meldingen sturen wanneer er iets gebeurt.`]},
 {h:`Wat moet je weten voordat je begint?`,ul:[`Biedt het systeem een API of export aan, en wat mag je ermee?`,`Welke gegevens wil je delen, en met welke rechten?`,`Wat gebeurt er als de koppeling uitvalt? Goede koppelingen melden fouten en proberen het opnieuw.`,`Wie onderhoudt de koppeling als een van de systemen verandert?`]},
 {h:`Onze werkwijze`,p:[`We bekijken eerst welke systemen, rechten en mogelijkheden er zijn. Daarna stellen we de eenvoudigste oplossing voor die het probleem echt oplost, en testen we die met echte situaties. Bewaking hoort erbij, zodat je het merkt als er iets hapert.`]}]},
{slug:'website-laten-maken-apeldoorn-bureau-kiezen',title:`Website laten maken in Apeldoorn: zo kies je het juiste bureau`,description:`Een website laten maken in Apeldoorn? Dit zijn de vragen die je een bureau of freelancer stelt voordat je kiest, en de signalen die je beter niet negeert.`,date:'2026-10-28',minutes:6,category:'Websites',blocks:[
 {p:[`Een website laten maken is een investering, en het aanbod is groot: freelancers, kleine studio’s, grotere bureaus en doe-het-zelf-pakketten. Voor ondernemers in Apeldoorn en omgeving komt daar een keuze bij: werk je met iemand uit de buurt, of kies je voor een partij ergens anders in het land? Hieronder lees je waar je op let, zodat je een keuze maakt die je over twee jaar nog steeds goed vindt.`]},
 {h:`Begin bij je doel, niet bij de prijs`,p:[`Vraag jezelf eerst af wat de site moet opleveren: meer aanvragen, online verkopen, vertrouwen wekken of werk besparen. Een goed bureau begint met dezelfde vraag. Een bureau dat meteen een prijs noemt zonder te vragen wat je wilt bereiken, schat waarschijnlijk op gevoel.`]},
 {h:`Vragen die je kunt stellen`,ul:[`Met wie werk ik samen, en wie bouwt de site daadwerkelijk? Bij kleine studio’s praat je vaak rechtstreeks met de maker.`,`Wat zit er in de prijs en wat niet? Denk aan teksten, beeld, hosting, een domeinnaam, onderhoud en een eerste ronde aanpassingen.`,`Van wie is de website als hij klaar is? Spreek vooraf af wie de rechten heeft en of je de bestanden en toegang krijgt.`,`Wat gebeurt er na oplevering? Vraag naar onderhoud, support en wat het kost als je later iets wilt aanpassen.`,`Wordt de site zoekmachinevriendelijk opgebouwd? Dat moet vanaf het begin worden meegenomen, niet achteraf.`,`Kan ik voorbeelden zien en met een eerdere klant praten of een review lezen?`]},
 {h:`Waarom lokaal kan helpen`,p:[`Een bureau in je eigen regio kan makkelijk langskomen, je bedrijf van dichtbij zien en snel schakelen. Dat maakt het gesprek persoonlijker. Het betekent niet dat een lokaal bureau automatisch beter is: kijk altijd naar het werk, de manier van werken en of je je prettig voelt bij het gesprek. Veel werk gaat tegenwoordig online, dus de afstand hoeft geen rol te spelen.`]},
 {h:`Signalen om voorzichtig mee te zijn`,ul:[`Een zeer lage vaste prijs zonder dat er naar je wensen is gevraagd.`,`Geen duidelijke afspraken over eigendom, hosting en onderhoud.`,`Beloftes over een nummer 1-positie in Google. Niemand kan een positie garanderen.`,`Een contract dat je lang vastzet zonder dat je weet wat je krijgt.`,`Geen portfolio of referenties die je kunt controleren.`]},
 {h:`Vergelijk offertes op inhoud`,p:[`Leg twee of drie offertes naast elkaar en vergelijk wat erin staat, niet alleen het totaalbedrag. Een goede offerte noemt de scope, de planning, wat je zelf moet aanleveren en wat er na oplevering gebeurt. Lees ook ons artikel over wat de prijs van een website bepaalt.`]},
 {h:`Onze aanpak`,p:[`NiMaGo is gevestigd in Apeldoorn. Je werkt rechtstreeks met de oprichter, krijgt vooraf een voorstel met scope, planning en prijs, en na oplevering regelen we op verzoek hosting en onderhoud. Een eerste gesprek is vrijblijvend, bij jou op locatie of online.`]}]},
{slug:'lokaal-gevonden-worden-google-bedrijfsprofiel',title:`Lokaal gevonden worden: je website en Google Bedrijfsprofiel`,description:`Wil je gevonden worden door klanten in je buurt? Zo laat je je website en Google Bedrijfsprofiel samenwerken, met een checklist voor lokale ondernemers.`,date:'2026-10-28',minutes:6,category:'Vindbaarheid',blocks:[
 {p:[`Als iemand zoekt op “loodgieter Apeldoorn” of “accountant in de buurt”, laat Google vaak eerst een kaart met bedrijven zien, daarna de gewone zoekresultaten. Wil je daar tussen staan, dan werken twee dingen samen: je Google Bedrijfsprofiel en je website. Dit artikel legt uit wat je zelf kunt doen.`]},
 {h:`Wat is een Google Bedrijfsprofiel?`,p:[`Het is een gratis vermelding van je bedrijf in Google Zoeken en Google Maps. Je vult je naam, categorie, adres of werkgebied, openingstijden, telefoonnummer, website en foto’s in. Klanten kunnen er reviews achterlaten. Voor lokale vindbaarheid is het meestal het belangrijkste wat je zelf kunt regelen.`]},
 {h:`Zo richt je het goed in`,ul:[`Maak een profiel aan op google.com/business en kies de categorie die het beste bij je werk past. Wees specifiek.`,`Vul alles volledig in en houd het actueel: openingstijden, telefoonnummer, website, diensten en foto’s.`,`Verifieer je profiel. Google vraagt daar een bevestiging voor, bijvoorbeeld per post, telefoon of video. Dit kan een paar dagen duren.`,`Werk je vanuit huis of bij klanten? Je kunt je adres verbergen en in plaats daarvan een werkgebied instellen.`,`Vraag tevreden klanten om een eerlijke review en reageer op elke review, ook de kritische.`]},
 {h:`Zorg voor dezelfde gegevens overal`,p:[`Naam, adres en telefoonnummer (in vakjargon NAP) moeten overal hetzelfde zijn: op je website, in je Google Bedrijfsprofiel, bij de KvK en op andere vermeldingen. Kleine afwijkingen, zoals een andere schrijfwijze van je bedrijfsnaam, maken het voor zoekmachines lastiger om te begrijpen dat het om hetzelfde bedrijf gaat.`]},
 {h:`Wat je website moet doen`,ul:[`Een duidelijke contactpagina met naam, adres of werkgebied, telefoonnummer en e-mailadres.`,`Pagina’s per dienst, met uitleg in gewone taal en de plaatsen waar je werkt.`,`Een snelle site die goed werkt op de telefoon. Veel lokale zoekopdrachten gebeuren onderweg.`,`Technische gegevens voor zoekmachines (gestructureerde gegevens) die vertellen wie je bent, wat je doet en waar.`,`Een link naar je website in je Google Bedrijfsprofiel, en andersom.`]},
 {h:`Wat je beter niet doet`,ul:[`Een bedrijfsnaam met extra zoekwoorden in je profiel zetten. Dat is tegen de regels van Google en kan je profiel kosten.`,`Reviews kopen of laten schrijven door bekenden die niet echt klant waren.`,`Een nepadres gebruiken om “lokaal” te lijken.`]},
 {h:`Hoe lang duurt het?`,p:[`Een nieuw profiel en een nieuwe website hebben tijd nodig. Reken op weken tot maanden voordat je zichtbaar stijgt, en nog langer in een drukke branche. Je kunt het niet afdwingen, maar je kunt wel zorgen dat de basis klopt en dat je elke week iets verbetert.`]}]},
{slug:'wat-is-geo-gevonden-worden-in-ai',title:`Wat is GEO? Zo word je gevonden in ChatGPT en andere AI-zoekmachines`,description:`Steeds meer mensen stellen hun vraag aan een AI-assistent. Wat is GEO, wat doet het anders dan SEO en wat kun je als ondernemer concreet doen?`,date:'2026-10-28',minutes:6,category:'Vindbaarheid',blocks:[
 {p:[`Naast Google gebruiken steeds meer mensen AI-assistenten zoals ChatGPT, Claude, Perplexity of de AI-overzichten in zoekmachines om iets op te zoeken. Zij geven een samengevat antwoord en noemen soms de bronnen. GEO, ofwel Generative Engine Optimization, gaat over de vraag hoe je ervoor zorgt dat jouw bedrijf in zulke antwoorden voorkomt.`]},
 {h:`Wat is het verschil met SEO?`,p:[`Bij SEO probeer je hoog in de lijst met zoekresultaten te komen. Bij GEO wil je dat een AI-systeem jouw bedrijf begrijpt, vertrouwt en noemt of citeert. De twee overlappen sterk: een technisch gezonde, duidelijke site met goede inhoud helpt voor allebei. Er bestaat geen truc die een vermelding garandeert, en niemand buiten de aanbieders weet precies hoe de systemen kiezen.`]},
 {h:`Wat helpt waarschijnlijk wel`,ul:[`Duidelijke feiten over je bedrijf op je site: wie je bent, wat je doet, waar je werkt, hoe je bereikbaar bent en je KvK-nummer.`,`Antwoorden op echte vragen in gewone taal, met een korte, directe samenvatting bovenaan en uitleg eronder.`,`Pagina’s per dienst en per onderwerp, in plaats van één pagina met alles.`,`Gestructureerde gegevens (schema.org) die de feiten machine-leesbaar maken.`,`Vermeldingen op andere betrouwbare plekken: KvK, Google Bedrijfsprofiel, brancheverenigingen, LinkedIn en echte reviews.`,`Een toegankelijke site: AI-crawlers moeten je pagina’s mogen lezen. Controleer je robots.txt.`]},
 {h:`Wat is llms.txt?`,p:[`Een llms.txt is een eenvoudig tekstbestand op je site met een samenvatting van je bedrijf en links naar de belangrijkste pagina’s, bedoeld voor AI-assistenten. Het is een voorstel, geen vaste standaard, en grote aanbieders hebben nog niet bevestigd dat ze het gebruiken. Het kost weinig moeite en schaadt niet, maar verwacht er geen wonderen van. Op deze website staan een llms.txt en een llms-full.txt.`]},
 {h:`Wat je beter niet verwacht`,ul:[`Dat je door een paar aanpassingen direct in ChatGPT wordt genoemd.`,`Dat je kunt sturen welk antwoord een AI geeft. Systemen kunnen fouten maken of verouderde informatie gebruiken.`,`Dat inhoud die alleen voor machines is geschreven goed werkt. Schrijf voor mensen en maak het daarnaast goed leesbaar voor machines.`]},
 {h:`Zo begin je`,ol:[`Zet de basisgegevens van je bedrijf helder op je site en houd ze overal hetzelfde.`,`Schrijf voor je belangrijkste diensten een pagina met uitleg en veelgestelde vragen.`,`Zorg dat je site snel, toegankelijk en technisch in orde is.`,`Bouw vermeldingen en reviews op die kloppen.`,`Test af en toe zelf: stel een AI-assistent de vragen die je klanten zouden stellen en kijk wat er gebeurt.`]}]},
{slug:'checklist-wat-heb-je-nodig-voor-een-website',title:`Checklist: wat heb je nodig voordat je een website laat maken?`,description:`Teksten, foto’s, domeinnaam, huisstijl: dit moet je klaar hebben of laten regelen voordat een website gebouwd wordt, zodat het project sneller en soepeler loopt.`,date:'2026-10-28',minutes:5,category:'Websites',blocks:[
 {p:[`De meeste vertraging bij een website ontstaat niet bij het bouwen, maar bij het wachten op teksten, foto’s en beslissingen. Met deze checklist ben je goed voorbereid en weet je wat je van een bureau mag verwachten.`]},
 {h:`1. Je doel en je doelgroep`,ul:[`Wat moet de website opleveren? Bijvoorbeeld meer aanvragen, afspraken, verkoop of vertrouwen.`,`Wie is je klant en wat wil die weten voordat hij contact opneemt?`,`Wat is de gewenste actie per pagina, zoals bellen, een formulier invullen of een afspraak plannen?`]},
 {h:`2. Teksten`,ul:[`Wie schrijft de teksten: jij, het bureau of een tekstschrijver? Spreek dat vooraf af.`,`Zorg voor een korte omschrijving per dienst, een over-ons-tekst en je contactgegevens.`,`Verzamel veelgestelde vragen van klanten. Dat zijn vaak de beste pagina’s.`]},
 {h:`3. Beeld`,ul:[`Echte foto’s van jezelf, je team, je werk of je producten werken beter dan stockbeelden.`,`Heb je een logo in een bruikbaar formaat (liefst vectorbestand)?`,`Je moet het recht hebben om de beelden te gebruiken. Controleer licenties.`]},
 {h:`4. Domeinnaam en e-mail`,ul:[`Heb je al een domeinnaam? Weet wie de eigenaar is en waar hij is geregistreerd.`,`Hoe loopt je e-mail? Overstappen van hosting kan invloed hebben op je mail, dus bespreek dit vooraf.`]},
 {h:`5. Huisstijl en voorbeelden`,ul:[`Kleuren, lettertypen en tone of voice, als je die hebt.`,`Drie websites die je mooi vindt en drie die je niet mooi vindt, met de reden erbij.`]},
 {h:`6. Wettelijke en praktische zaken`,ul:[`Bedrijfsgegevens zoals KvK-nummer, btw-nummer en adres voor op de site.`,`Een privacyverklaring en algemene voorwaarden. Laat die controleren als je ze zelf laat opstellen.`,`Wie beheert de site na oplevering en wie lost problemen op?`]},
 {h:`7. Planning en beslissers`,ul:[`Wie keurt teksten en ontwerp goed? Eén aanspreekpunt scheelt veel tijd.`,`Is er een datum waarop de site live moet, bijvoorbeeld door een campagne of opening?`]},
 {p:[`Heb je nog niet alles? Dat is niet erg. Een goed bureau helpt je met structuur, teksten en beeld, maar hoe meer je zelf aanlevert, hoe sneller de site klaar is.`]}]},
{slug:'zoekmachineoptimalisatie-voor-ondernemers',title:`Zoekmachineoptimalisatie (SEO) voor ondernemers: zo begin je`,description:`SEO uitgelegd in gewone taal: wat het is, wat je zelf kunt doen en wat je beter overlaat aan een specialist. Met een praktisch stappenplan voor beginners.`,date:'2026-10-28',minutes:6,category:'Vindbaarheid',blocks:[
 {p:[`SEO staat voor zoekmachineoptimalisatie: het zorgen dat je website goed gevonden wordt in Google en andere zoekmachines. Je hoeft er geen specialist voor te zijn om de basis op orde te brengen. Dit artikel laat zien wat belangrijk is en in welke volgorde.`]},
 {h:`Hoe werkt een zoekmachine in het kort?`,p:[`Een zoekmachine bekijkt je website met een programma dat pagina’s leest (crawlen), bewaart wat het vindt (indexeren) en bepaalt bij een zoekopdracht welke pagina’s het beste antwoord geven (rangschikken). Je kunt dat proces niet afdwingen, wel zorg je dat je pagina’s vindbaar, snel en duidelijk zijn.`]},
 {h:`Stap 1: weet waar je klanten naar zoeken`,p:[`Bedenk welke woorden en vragen een klant gebruikt voordat hij je kent. Niet “digitale transformatie”, maar “website laten maken” of “wat kost een webshop”. Combineer ze met je werkgebied als je lokaal werkt. Google Search Console laat je later zien op welke zoektermen je al vertoond wordt.`]},
 {h:`Stap 2: één onderwerp per pagina`,ul:[`Geef elke dienst of elk onderwerp een eigen pagina met een duidelijke titel en een kop (H1) die past bij wat mensen zoeken.`,`Schrijf een korte, aantrekkelijke omschrijving (meta description) per pagina. Die toont Google vaak onder je titel.`,`Beantwoord de vraag echt en volledig, in gewone taal. Kopieer geen teksten van anderen.`]},
 {h:`Stap 3: de techniek op orde`,ul:[`Zorg dat de site snel laadt en goed werkt op een telefoon.`,`Gebruik https en laat geen kapotte pagina’s achter.`,`Stuur een sitemap in via Google Search Console en controleer dat je robots.txt je pagina’s niet blokkeert.`,`Geef afbeeldingen een korte beschrijving (alt-tekst).`]},
 {h:`Stap 4: laat zien dat je te vertrouwen bent`,ul:[`Toon duidelijk wie je bent, met contactgegevens en bedrijfsgegevens.`,`Verzamel eerlijke reviews en laat echte projecten zien.`,`Zorg voor vermeldingen op andere betrouwbare sites, zoals de KvK en je Google Bedrijfsprofiel.`]},
 {h:`Stap 5: blijf nieuwe, nuttige inhoud toevoegen`,p:[`Een artikel of project per week of per maand dat echte vragen van klanten beantwoordt, werkt beter dan één keer veel schrijven en daarna niets meer. Zoekmachines zien dat je site actueel is, en je krijgt meer pagina’s waarop je gevonden kunt worden.`]},
 {h:`Wat kost het en hoe lang duurt het?`,p:[`SEO is geen eenmalige actie. Een nieuwe website kan weken tot maanden nodig hebben om zichtbaar te worden, afhankelijk van de concurrentie. Wees voorzichtig met partijen die snelle resultaten of een eerste plek garanderen: dat kan niemand beloven.`]},
 {h:`Wat laat je aan een specialist?`,p:[`Technische audits, grote migraties, zware concurrentie en internationale sites vragen vaak om specialistische hulp. De basis in dit artikel kun je zelf, of samen met je webbouwer, goed neerzetten.`]}]},
{slug:'webshop-starten-checklist',title:`Een webshop starten: de checklist voor je eerste webshop`,description:`Een eigen webshop starten? Dit heb je nodig: producten, betalingen, verzending, btw en de regels voor online verkoop aan consumenten, in een overzichtelijke checklist.`,date:'2026-11-04',minutes:6,category:'Webshops',blocks:[
 {p:[`Een webshop starten lijkt eenvoudig: je zet producten online en wacht op bestellingen. In de praktijk komen er meer onderdelen bij kijken dan een mooi ontwerp. Met deze checklist loop je ze langs, zodat je niets vergeet voordat je live gaat.`]},
 {h:`1. Je assortiment en je producten`,ul:[`Heb je per product goede foto’s, een duidelijke omschrijving, een prijs en eventueel varianten (maat, kleur)?`,`Hoe houd je voorraad bij, en wat gebeurt er als iets uitverkocht is?`,`Hoe ga je met productgegevens om als je assortiment groeit? Een lijst in een spreadsheet werkt in het begin, een koppeling met je administratie later beter.`]},
 {h:`2. Betalen`,ul:[`Kies de betaalmethoden die je klanten gebruiken. In Nederland is iDEAL voor veel klanten vanzelfsprekend.`,`Een betaalprovider regelt de veilige afhandeling. Vergelijk de kosten per transactie en de voorwaarden.`,`Bepaal hoe je omgaat met terugbetalingen en mislukte betalingen.`]},
 {h:`3. Verzending en retouren`,ul:[`Welke vervoerders en tarieven gebruik je, en verzend je ook naar het buitenland?`,`Hoe maak je verzendlabels aan, en wat kost verpakking?`,`Stel een duidelijk retourproces in en vermeld het op je site.`]},
 {h:`4. Btw en administratie`,ul:[`Bepaal welk btw-tarief op welk product van toepassing is, en bespreek verkoop naar andere EU-landen met je boekhouder.`,`Zorg dat bestellingen netjes in je boekhouding terechtkomen. Een koppeling met je boekhoudpakket scheelt veel handwerk.`]},
 {h:`5. Regels voor online verkoop aan consumenten`,p:[`Verkoop je aan consumenten, dan gelden er wettelijke regels. Denk aan duidelijke informatie over het product, de totale prijs, de leveringsvoorwaarden en het herroepingsrecht (de bedenktijd van 14 dagen voor veel aankopen op afstand). Zorg ook voor algemene voorwaarden, een privacyverklaring en je bedrijfsgegevens op de site. Laat dit controleren door een jurist of een brancheorganisatie voordat je live gaat; wij geven geen juridisch advies.`]},
 {h:`6. Platform of maatwerk?`,p:[`Voor de meeste startende webshops is een bewezen platform zoals Shopify of WooCommerce een goede keuze. Maatwerk gaat pas lonen als je processen echt afwijken. Lees ons artikel over Shopify of een maatwerk webshop voor de afwegingen.`]},
 {h:`7. Testen voor je live gaat`,ul:[`Doe zelf een testbestelling van begin tot eind, inclusief betalen, bevestigingsmail en retour.`,`Test op een telefoon: veel klanten bestellen daarop.`,`Controleer dat je e-mails niet in de spam belanden.`]},
 {h:`8. Na de start`,p:[`Kijk de eerste weken welke producten bekeken maar niet gekocht worden, waar bezoekers afhaken en welke vragen klanten stellen. Verbeter in kleine stappen. Een webshop is nooit helemaal af.`]}]},
{slug:'hosting-kiezen-voor-je-website',title:`Hosting kiezen voor je website: waar let je op?`,description:`Wat is hosting en wat doet een goede hostingpartij? Dit zijn de punten die ertoe doen: snelheid, back-ups, beveiliging, locatie van je data en support.`,date:'2026-11-11',minutes:5,category:'Onderhoud',blocks:[
 {p:[`Hosting is de plek waar je website draait. Je merkt het pas als het misgaat: de site is traag, onbereikbaar of er is data kwijt. Daarom is het slim om vooraf te weten waar je op let.`]},
 {h:`Wat is hosting precies?`,p:[`Een website bestaat uit bestanden en vaak een database. Die staan op een server die altijd aan staat en verbonden is met internet. Een hostingpartij verhuurt die ruimte en regelt de techniek eromheen, zoals stroom, netwerk en beveiliging. Je domeinnaam (zoals jouwbedrijf.nl) is iets anders: dat is het adres waarmee mensen je site vinden.`]},
 {h:`Waar let je op?`,ul:[`Betrouwbaarheid: hoe vaak ligt de dienst eruit, en wat belooft de aanbieder over bereikbaarheid?`,`Snelheid: de locatie van de server en de kwaliteit van de hardware bepalen hoe snel je site laadt.`,`Back-ups: worden er automatisch back-ups gemaakt, hoe vaak, en hoe haal je ze terug? Bewaar liefst ook zelf een kopie.`,`Beveiliging: https (SSL-certificaat), updates en bescherming tegen aanvallen.`,`Locatie van je gegevens: voor persoonsgegevens van klanten is het fijn als de data binnen de EU blijft.`,`Support: kun je iemand bereiken als er iets misgaat, en hoe snel?`,`Schaalbaarheid: kun je meegroeien als je meer bezoekers krijgt?`]},
 {h:`Soorten hosting`,ul:[`Gedeelde hosting: veel sites op één server. Goedkoop, prima voor een kleine site, maar je deelt de capaciteit.`,`VPS of cloudserver: meer controle en eigen capaciteit, maar er is technische kennis nodig voor beheer.`,`Beheerde hosting: de aanbieder regelt updates en beveiliging voor je. Duurder, maar minder zorg.`,`Platformen zoals Shopify of Vercel: hosting is inbegrepen bij het platform.`]},
 {h:`Eigendom en overstappen`,p:[`Zorg dat je domeinnaam op jouw naam staat en dat je toegang hebt tot je hostingaccount. Vraag bij een bureau hoe dat geregeld is. Zo kun je later overstappen zonder gedoe.`]},
 {h:`Wat kost het?`,p:[`De prijzen lopen sterk uiteen, van een paar euro per maand voor een eenvoudige site tot een stuk meer voor beheerde hosting of een drukke webshop. Vergelijk niet alleen de prijs, maar ook wat erin zit: back-ups, support en beveiliging.`]},
 {h:`Hosting en onderhoud samen`,p:[`Bij NiMaGo regelen we op verzoek hosting, domein en onderhoud, zodat je er zelf niets van hoeft te weten. Je blijft eigenaar van je site en je gegevens.`]}]},
{slug:'nextjs-of-wordpress-welke-past-bij-jou',title:`Next.js of WordPress: welke techniek past bij jouw website?`,description:`WordPress of een moderne techniek als Next.js? Een eerlijke vergelijking voor ondernemers: beheer, snelheid, kosten, onderhoud en wanneer welke keuze past.`,date:'2026-11-18',minutes:6,category:'Websites',blocks:[
 {p:[`Als je een website laat maken, hoor je al snel de namen WordPress en Next.js. Beide zijn goede keuzes, maar voor andere situaties. Dit artikel legt uit wat het verschil is, zonder jargon.`]},
 {h:`Wat is WordPress?`,p:[`WordPress is een contentmanagementsysteem (CMS) waarmee veel websites zijn gebouwd. Je beheert teksten en pagina’s zelf in een beheeromgeving en kunt met plug-ins functies toevoegen. Het heeft een enorme gemeenschap en veel kant-en-klare thema’s.`]},
 {h:`Wat is Next.js?`,p:[`Next.js is een raamwerk om websites en webapplicaties op maat te bouwen. Een ontwikkelaar schrijft de site in code, vaak gekoppeld aan een eigen beheeromgeving of een extern CMS. Je krijgt veel vrijheid in ontwerp, snelheid en functies.`]},
 {h:`De belangrijkste verschillen`,ul:[`Beheer: WordPress is direct klaar voor zelfstandig beheer. Bij Next.js moet het beheer erbij gebouwd of gekoppeld worden.`,`Ontwerp en vrijheid: met Next.js kun je alles op maat maken. Met WordPress werk je vaak vanuit een thema en plug-ins.`,`Snelheid: een goed gebouwde Next.js-site is doorgaans zeer snel. WordPress kan ook snel zijn, maar veel plug-ins kunnen het vertragen.`,`Onderhoud en beveiliging: WordPress en plug-ins vragen regelmatig updates. Een maatwerksite heeft minder losse onderdelen, maar heeft wel een ontwikkelaar nodig voor wijzigingen.`,`Kosten: een WordPress-site met een bestaand thema is meestal sneller en goedkoper te starten. Maatwerk kost vooraf meer, maar past beter bij bijzondere wensen.`]},
 {h:`Wanneer past WordPress?`,ul:[`Je wilt zelf veel teksten en pagina’s kunnen aanpassen.`,`Je hebt een standaardwebsite of blog nodig en je budget is beperkt.`,`Je hebt al een WordPress-site die goed werkt.`]},
 {h:`Wanneer past Next.js of maatwerk?`,ul:[`Je wilt een onderscheidend ontwerp dat niet op een thema lijkt.`,`Je hebt functies nodig die niet in een standaardpakket zitten, zoals een klantportaal of koppelingen met je systemen.`,`Snelheid en een lage onderhoudslast zijn belangrijk.`]},
 {h:`Ons advies`,p:[`Kies niet op basis van een naam, maar op wat je nodig hebt. NiMaGo bouwt voornamelijk met moderne technieken zoals Next.js, maar we adviseren een eenvoudiger oplossing als die beter past. Een eerste gesprek is vrijblijvend.`]}]},
{slug:'avg-en-je-website-basis-voor-ondernemers',title:`AVG en je website: de basis voor ondernemers`,description:`Wat moet je regelen voor de privacywetgeving (AVG) op je website? Privacyverklaring, formulieren, cookies en bewaartermijnen uitgelegd voor ondernemers.`,date:'2026-11-25',minutes:6,category:'Juridisch',blocks:[
 {p:[`Heeft je website een contactformulier, nieuwsbrief of statistieken? Dan verwerk je persoonsgegevens en gelden er regels uit de Algemene verordening gegevensbescherming (AVG). Dit artikel geeft een eerste overzicht. Het is geen juridisch advies: laat je situatie controleren door een jurist of de Autoriteit Persoonsgegevens.`]},
 {h:`Wat zijn persoonsgegevens?`,p:[`Alles wat iets zegt over een herkenbaar persoon: naam, e-mailadres, telefoonnummer, maar ook een IP-adres in combinatie met andere gegevens. Zodra je zulke gegevens opslaat of gebruikt, ben je verantwoordelijk voor een zorgvuldige omgang.`]},
 {h:`Wat moet je minimaal regelen?`,ul:[`Een privacyverklaring op je site. Die zegt wie je bent, welke gegevens je verwerkt, waarvoor, hoe lang je ze bewaart, met wie je ze deelt en welke rechten mensen hebben.`,`Een reden voor elke verwerking, zoals een overeenkomst, een wettelijke plicht, toestemming of een gerechtvaardigd belang.`,`Alleen verzamelen wat je echt nodig hebt (dataminimalisatie).`,`Duidelijke bewaartermijnen en je gegevens weer verwijderen als je ze niet meer nodig hebt.`,`Een beveiligde website (https) en beveiligde opslag.`]},
 {h:`Contactformulieren en nieuwsbrieven`,ul:[`Vraag alleen om gegevens die je nodig hebt om te antwoorden.`,`Voor een nieuwsbrief heb je meestal toestemming nodig, en moet afmelden even makkelijk zijn als aanmelden.`,`Verwijs bij het formulier naar je privacyverklaring.`]},
 {h:`Cookies en statistieken`,p:[`Voor cookies en vergelijkbare technieken geldt in Nederland de Telecommunicatiewet, naast de AVG. Cookies die nodig zijn om de site te laten werken, vragen geen toestemming. Voor tracking- en advertentiecookies is vooraf toestemming nodig. Sommige analysemethoden zijn zo privacyvriendelijk ingericht dat ze zonder toestemming kunnen, maar dat moet je zorgvuldig toetsen. Een eenvoudige oplossing is statistieken gebruiken die geen cookies plaatsen en geen persoonsgegevens opslaan.`]},
 {h:`Externe partijen`,p:[`Gebruik je externe diensten, zoals een mailprovider, hostingpartij of betaalprovider, dan delen ze vaak gegevens van jouw bezoekers of klanten. Maak daar afspraken over en noem ze in je privacyverklaring. Soms is een verwerkersovereenkomst nodig.`]},
 {h:`Wat als er iets misgaat?`,p:[`Bij een datalek, bijvoorbeeld een gestolen of verloren bestand met persoonsgegevens, kan er een meldplicht zijn bij de Autoriteit Persoonsgegevens, vaak binnen 72 uur. Noteer incidenten en weet vooraf wie wat doet.`]},
 {h:`Praktisch advies`,p:[`Een goede website is vanaf de start zo gebouwd dat hij weinig gegevens verzamelt en veilig omgaat met wat nodig is. NiMaGo bouwt zo, maar de juridische teksten en je eigen verwerkingen moet je altijd zelf laten toetsen.`]}]},
{slug:'website-teksten-die-klanten-overtuigen',title:`Website-teksten die klanten overtuigen: zo schrijf je ze`,description:`Goede website-teksten laten bezoekers contact opnemen. Praktische tips voor ondernemers: schrijf helder, begin bij de vraag van de klant en eindig met een duidelijke stap.`,date:'2026-12-02',minutes:5,category:'Websites',blocks:[
 {p:[`Een mooi ontwerp trekt de aandacht, maar de tekst zorgt dat iemand blijft lezen en contact opneemt. Gelukkig hoef je geen tekstschrijver te zijn om duidelijke teksten te maken. Met deze tips schrijf je teksten die bezoekers helpen en vindbaar zijn.`]},
 {h:`Begin bij de vraag van je klant`,p:[`Schrijf niet over wat jij allemaal doet, maar over het probleem dat je klant wil oplossen. Een bezoeker vraagt zich in een paar seconden af: ben ik hier goed? Laat dat zien in je kop en eerste zin.`]},
 {h:`Zeg het simpel`,ul:[`Gebruik korte zinnen en gewone woorden. Vermijd vakjargon, of leg het uit.`,`Schrijf in de jij- of u-vorm, passend bij je klanten, en houd dat vol.`,`Eén gedachte per alinea, en kopjes waar de lezer op kan scannen.`]},
 {h:`Maak het concreet`,ul:[`Noem wat je doet, voor wie, en wat de klant eraan heeft.`,`Gebruik echte voorbeelden, getallen die je kunt verantwoorden en korte klantverhalen.`,`Vermijd lege woorden als “innovatief”, “kwalitatief” en “professioneel” zonder uitleg.`]},
 {h:`Geef een duidelijke volgende stap`,p:[`Eindig elke pagina met wat de bezoeker nu kan doen: bel, plan een afspraak, vraag een offerte aan. Maak de stap klein en concreet, bijvoorbeeld “Plan een vrijblijvende kennismaking van 30 minuten”.`]},
 {h:`Schrijf voor mensen én zoekmachines`,ul:[`Gebruik de woorden die je klanten gebruiken, zoals “website laten maken” in plaats van interne termen.`,`Zet je belangrijkste woorden in de kop, de eerste alinea en de titel van de pagina, maar blijf natuurlijk schrijven.`,`Beantwoord veelgestelde vragen op je site. Dat helpt bezoekers én zoekmachines.`]},
 {h:`Controleer en test`,ul:[`Lees je tekst hardop. Klinkt het onnatuurlijk, dan schrijf je het anders.`,`Laat iemand buiten je bedrijf meelezen en kijk waar die haperen.`,`Kijk later in je statistieken welke pagina’s bezocht worden en pas teksten aan waar bezoekers afhaken.`]},
 {h:`Hulp nodig?`,p:[`Teksten zijn vaak het lastigste onderdeel van een nieuwe website. Wij denken mee over structuur en formulering, en werken desgewenst samen met een tekstschrijver.`]}]},
{slug:'softwarebedrijf-kiezen-in-apeldoorn',title:`Softwarebedrijf kiezen in Apeldoorn: waar let je op?`,description:`Op zoek naar een softwarebedrijf in Apeldoorn? Dit zijn de vragen die je stelt, de verschillen tussen maatwerk en standaard en de signalen om op te letten.`,date:'2026-10-28',minutes:6,category:'Maatwerk',blocks:[
 {p:[`Als je software laat bouwen, geef je een stuk van je bedrijfsvoering uit handen. Dan wil je zeker weten dat je met de juiste partij in zee gaat. Voor ondernemers in Apeldoorn en omgeving helpt het om te weten waar je op kunt letten, en wat het verschil is tussen een softwarebedrijf, een webbureau en een standaardpakket.`]},
 {h:`Wat doet een softwarebedrijf?`,p:[`Een softwarebedrijf ontwerpt, bouwt en onderhoudt software. Dat kan een website met extra functies zijn, een klantportaal, een planningstool, een dashboard of een koppeling tussen systemen. Het verschil met een standaardpakket is dat maatwerk software wordt gebouwd rond jouw werkwijze, in plaats van dat jij je werkwijze aanpast.`]},
 {h:`Maatwerk of standaard?`,ul:[`Standaardsoftware is sneller en goedkoper te starten en past als je proces gewoon is.`,`Maatwerk past als je proces afwijkt, als je een onderscheidende klantervaring wilt, of als je meerdere systemen moet laten samenwerken.`,`Soms is de beste oplossing een combinatie: een standaardpakket met een maatwerkkoppeling of -portaal eromheen.`]},
 {h:`Vragen die je een softwarebedrijf stelt`,ul:[`Begint u bij mijn werkproces of bij de techniek?`,`Werken we in kleine stappen, zodat ik regelmatig iets werkends zie?`,`Wie bouwt de software en met wie praat ik?`,`Van wie is de software en de broncode na oplevering?`,`Wat gebeurt er na de oplevering: beheer, updates, fouten en doorontwikkeling?`,`Hoe gaat u om met beveiliging en met persoonsgegevens?`,`Kan ik voorbeelden van eerder werk zien?`]},
 {h:`Signalen om op te letten`,ul:[`Een vaste prijs voor een groot project zonder dat er een goed gesprek aan voorafging.`,`Geen duidelijke afspraken over eigendom en beheer.`,`Een softwarebedrijf dat alleen praat over techniek en niet over wat het jou oplevert.`,`Beloftes die te mooi klinken, zoals “af in twee weken” voor iets groots.`]},
 {h:`Waarom een softwarebedrijf in de buurt?`,p:[`Een softwarebedrijf in Apeldoorn kan makkelijk langskomen, je werkplek en proces van dichtbij zien en snel schakelen. Dat maakt het gesprek persoonlijker en voorkomt misverstanden. Het is geen garantie voor kwaliteit: kijk altijd naar werkwijze, voorbeelden en hoe het gesprek voelt.`]},
 {h:`Onze aanpak`,p:[`NiMaGo is een softwarebedrijf in Apeldoorn. We beginnen bij je proces, werken in kleine stappen en leggen vooraf scope, planning en prijs per fase vast. Een eerste gesprek is vrijblijvend, bij jou op locatie of online.`]}]},
];
/** Artikelen met een datum in de toekomst zijn klaargezet en verschijnen vanzelf op die dag (tijdzone Amsterdam): in lijsten, de sitemap, llms.txt en als pagina. */
const todayAms=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Amsterdam'}).format(new Date());
const published=()=>allArticles.filter(a=>a.date<=todayAms());
export const articles:Article[]=new Proxy([] as Article[],{get:(_,p)=>Reflect.get(published(),p),has:(_,p)=>Reflect.has(published(),p),ownKeys:()=>Reflect.ownKeys(published()),getOwnPropertyDescriptor:(_,p)=>Reflect.getOwnPropertyDescriptor(published(),p)});
export const scheduledArticles=()=>allArticles.filter(a=>a.date>todayAms()).map(a=>({slug:a.slug,title:a.title,date:a.date}));

