/** Inhoudelijke vervolgartikelen; geplande artikelen blijven via articles uitgesloten. */
const articleClusters:Record<string,string[]>={
 'Maatwerk':['Automatisering','Koppelingen'],
 'Automatisering':['Koppelingen','Maatwerk'],
 'Koppelingen':['Automatisering','Maatwerk'],
 'Websites':['Onderhoud','Vindbaarheid'],
 'Webshops':['Koppelingen','Websites'],
 'Onderhoud':['Websites','Juridisch'],
 'Vindbaarheid':['Websites'],
 'Juridisch':['Onderhoud','Websites']
};
export function relatedArticles(article:Article,limit=3):Article[]{
 const categories=[article.category,...(articleClusters[article.category]||[])];
 return articles.filter(a=>a.slug!==article.slug&&categories.includes(a.category))
  .sort((a,b)=>categories.indexOf(a.category)-categories.indexOf(b.category)||b.date.localeCompare(a.date)||a.slug.localeCompare(b.slug)).slice(0,limit);
}
